//! Serializable store snapshot: the typed shape of the prepopulated fixture.
//!
//! `StoreSnapshot` is a standalone serializable value type — the typed struct
//! that `SNAPSHOT_JSON` deserializes into. It is not test-gated: the sqlx
//! integration suites load the fixture by direct JSON deserialization into
//! this type, with no dependency on the in-memory `MemStore`.
//!
//! The fixture JSON (`SNAPSHOT_JSON`) is generated by the `build-snapshot`
//! bin and checked in; it is the same data the in-memory store suite runs
//! against.

pub use crate::prepopulated_data::SNAPSHOT_JSON;

use crate::{Activity, Attachment, Part, Usage, User};

/// Serializable snapshot of store data for JSON persistence.
#[derive(Debug, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct StoreSnapshot {
    pub users: Vec<User>,
    pub parts: Vec<Part>,
    pub attachments: Vec<Attachment>,
    pub usages: Vec<Usage>,
    pub activities: Vec<Activity>,
}

/// Load the prepopulated fixture by direct JSON deserialization into
/// `StoreSnapshot`. This is the sqlx seed path: no `MemStore` round-trip.
pub fn load_snapshot() -> StoreSnapshot {
    serde_json::from_str(SNAPSHOT_JSON).expect("SNAPSHOT_JSON must be valid JSON")
}
